You are a Dubai real estate lead qualification AI.

Analyze this lead.

Name: {{ $json.Name }}
Email: {{ $json.Email }}
Message: {{ $json.Message }}

Return ONLY valid JSON in this format:

{
  "lead_type": "",
  "priority": "",
  "lead_score": 0,
  "sentiment": "",
  "investment_interest": "",
  "recommended_team": "",
  "summary": ""
}

parameters.jsCode:
return $input.all().map(item => {
  const j = item.json || {};
  let raw = '{}';
  if (j.output && j.output[0] && j.output[0].content && j.output[0].content[0] && j.output[0].content[0].text) {
    raw = j.output[0].content[0].text;
  } else if (typeof j.text === 'string') {
    raw = j.text;
  } else if (j.message && typeof j.message.content === 'string') {
    raw = j.message.content;
  }
  let d = {};
  try { d = JSON.parse(raw); } catch (e) { d = {}; }
  return { json: {
    LeadType: d.LeadType || '',
    Budget: d.Budget || '',
    InvestmentInterest: d.InvestmentInterest || '',
    AreaPreference: d.AreaPreference || '',
    Sentiment: d.Sentiment || '',
    Priority: d.Priority || '',
    RecommendedSalesTeam: d.RecommendedSalesTeam || '',
    LeadScore: d.LeadScore != null ? d.LeadScore : 0,
    ConfidenceScore: d.ConfidenceScore != null ? d.ConfidenceScore : 0,
    AIReason: d.AIReason || ''
  }};
});

const webhook = $('Lead Webhook (HTTP)').first().json.body || {};
const items = $input.all();

return items.map(item => {
  const j = item.json || {};

  let aiData =
    j.output?.[0]?.content?.[0]?.text ??
    j.text ??
    j.message?.content ??
    {};

  // Parse AI response if it is returned as text
  if (typeof aiData === 'string') {
    aiData = aiData
      .replace(/```json/gi, '')
      .replace(/```/g, '')
      .trim();

    try {
      aiData = JSON.parse(aiData);
    } catch (error) {
      aiData = {};
    }
  }

  return {
    json: {
      Name:
        webhook.Name ||
        webhook.name ||
        '',

      Email:
        webhook.Email ||
        webhook.email ||
        '',

      Message:
        webhook.Message ||
        webhook.message ||
        '',

      'AI Budget':
        aiData['AI Budget'] ||
        aiData.AIBudget ||
        aiData.Budget ||
        '',

      Phone:
        webhook.Phone ||
        webhook.phone ||
        webhook.Mobile ||
        webhook.mobile ||
        '',

      'AI Area Preference':
        aiData['AI Area Preference'] ||
        aiData.AIAreaPreference ||
        aiData.AreaPreference ||
        '',

      'Date Received':
        webhook['Date Received'] ||
        webhook.Date ||
        webhook.date ||
        new Date().toLocaleDateString('en-GB', {
          timeZone: 'Asia/Dubai'
        }),

      'Time Received':
        webhook['Time Received'] ||
        webhook.Time ||
        webhook.time ||
        new Date().toLocaleTimeString('en-US', {
          timeZone: 'Asia/Dubai',
          hour: '2-digit',
          minute: '2-digit',
          hour12: true
        }),

      'Page URL':
        webhook['Page URL'] ||
        webhook.PageURL ||
        webhook.page_url ||
        webhook.url ||
        '',

      Subject:
        aiData.Subject ||
        'Your property enquiry',

      EmailDraft:
        aiData.EmailDraft ||
        '',

      WhatsAppDraft:
        aiData.WhatsAppDraft ||
        ''
    }
  };
});

